# convert iron ore station blueprint to copper ore station blueprint.

# actually better yet, figure out what the receiving item blueprint is and then change 
# it accordingly 
import time
from add_modules import add_max_modules
from convert_json_to_blueprint_string import *
from recipe_extraction import *
import ast
import json,copy,math,pyperclip, numpy
import itertools
from pathlib import Path


SOLID_INGREDIENT_STATION_TEMPLATE = Path(
	"blueprints/advanced_circuit_station.json"
)
ROBOPORT_STATION_TEMPLATE = Path(
	"blueprints/stations/repositories/roboport_station.json"
)
INTERSECTION_TEMPLATE = Path(
	"blueprints/train_track_intersection.json"
)
PLASTIC_BAR_STATION_TEMPLATE = Path(
	"blueprints/stations/plastic_bar.json"
)
ROBOPORT_STATION_ALIASES = {"roboport_station", "robort_station"}

FACTORIO_2_ENTITY_NAMES = {
	"logistic-chest-requester": "requester-chest",
	"logistic-chest-active-provider": "active-provider-chest",
	"logistic-chest-passive-provider": "passive-provider-chest",
	"logistic-chest-storage": "storage-chest",
	"logistic-chest-buffer": "buffer-chest",
	"stack-inserter": "bulk-inserter",
	"curved-rail": "legacy-curved-rail",
}

LOCOMOTIVE_COAL_COUNT = 25


def add_midpoints_to_train_schedule(schedule, *, skip_midpoint_stations=()):
	"""Return a schedule whose every endpoint is preceded by its midpoint.

	``schedule`` may be a Factorio ``{"records": [...]}`` schedule value or a
	bare record list. Existing midpoints are rebuilt, so this is idempotent and
	stations named in ``skip_midpoint_stations`` are retained without a midpoint.
	"""
	is_schedule_value = isinstance(schedule, dict)
	records = schedule.get("records", []) if is_schedule_value else schedule
	if not isinstance(records, list):
		raise ValueError("Train schedule records must be a list")

	skip_midpoint_stations = set(skip_midpoint_stations)
	result = []
	for record in records:
		station = record.get("station", "")
		if not station or station.endswith(" midpoint"):
			continue
		endpoint = copy.deepcopy(record)
		if station not in skip_midpoint_stations:
			result.append({"station": f"{station} midpoint"})
		result.append(endpoint)

	if is_schedule_value:
		normalized = copy.deepcopy(schedule)
		normalized["records"] = result
		return normalized
	return result


def _put_midpoint_before_each_scheduled_stop(records):
	"""Backward-compatible wrapper for older callers."""
	return add_midpoints_to_train_schedule(records)


def _pair_midpoints_with_physical_stops(entities):
	"""Pair every physical stop with its farthest midpoint, one-to-one."""
	physical_stops = [
		entity for entity in entities
		if entity.get("name") == "train-stop"
		and not entity.get("station", "").endswith(" midpoint")
	]
	midpoints = [
		entity for entity in entities
		if entity.get("name") == "train-stop"
		and entity.get("station", "").endswith(" midpoint")
	]
	if not midpoints:
		return
	if len(midpoints) != len(physical_stops):
		raise ValueError(
			"Every physical station stop must have exactly one midpoint stop"
		)

	physical_stops.sort(key=lambda entity: entity["entity_number"])
	midpoints.sort(key=lambda entity: entity["entity_number"])

	def squared_distance(stop, midpoint):
		return (
			(stop["position"]["x"] - midpoint["position"]["x"]) ** 2
			+ (stop["position"]["y"] - midpoint["position"]["y"]) ** 2
		)

	# There are four endpoints in the station template (only 4! possible
	# assignments). Choosing the maximum total distance gives every endpoint the
	# midpoint on the opposite end without allowing a midpoint to be reused.
	assignment = max(
		itertools.permutations(midpoints),
		key=lambda candidate: sum(
			squared_distance(stop, midpoint)
			for stop, midpoint in zip(physical_stops, candidate)
		),
	)
	for stop, midpoint in zip(physical_stops, assignment):
		midpoint["station"] = f'{stop["station"]} midpoint'


def fill_locomotives_with_coal(blueprint):
	"""Give every generated locomotive exactly 25 coal."""
	for entity in blueprint.get("blueprint", {}).get("entities", []):
		if entity.get("name") != "locomotive":
			continue
		# Factorio 2 exports this field on rolling stock. Older depot templates
		# omit it, which can cause the locomotives to be skipped while their
		# wagons are still placed.
		entity["enable_logistics_while_moving"] = False
		entity["items"] = [{
			"id": {"name": "coal"},
			"items": {
				"in_inventory": [
					{
						"inventory": 1,
						"stack": 0,
						"count": LOCOMOTIVE_COAL_COUNT,
					}
				],
			},
		}]
	return blueprint


def set_trains_per_stop(blueprint, trains_per_stop=1):
	"""Set how many trains may simultaneously target each train stop."""
	if not isinstance(trains_per_stop, int) or isinstance(trains_per_stop, bool):
		raise ValueError("trains_per_stop must be a positive integer")
	if trains_per_stop < 1:
		raise ValueError("trains_per_stop must be a positive integer")
	for entity in blueprint.get("blueprint", {}).get("entities", []):
		if entity.get("name") == "train-stop":
			entity["manual_trains_limit"] = trains_per_stop
	return blueprint


def _load_blueprint_file(filename):
	"""Load either normal JSON or an exported Python-dict blueprint file."""
	contents = Path(filename).read_text(encoding="utf-8-sig")
	try:
		return json.loads(contents)
	except json.JSONDecodeError:
		return ast.literal_eval(contents)


def _request_filter_names(entity):
	"""Return item names from both Factorio 1.1 and 2.0 request formats."""
	request_filters = entity.get("request_filters", [])
	if isinstance(request_filters, dict):
		return [
			item["name"]
			for section in request_filters.get("sections", [])
			for item in section.get("filters", [])
			if "name" in item
		]
	return [item["name"] for item in request_filters if "name" in item]


def _normalize_factorio_2_entity_names(entities, inserter="bulk-inserter"):
	"""Convert legacy blueprint prototype names to their Factorio 2 names."""
	for entity in entities:
		entity["name"] = FACTORIO_2_ENTITY_NAMES.get(
			entity["name"],
			entity["name"],
		)
		if entity["name"].endswith("inserter"):
			entity["name"] = inserter


def _factorio_2_request_filters(ingredients):
	filters = []
	for index, ingredient in enumerate(ingredients, 1):
		filters.append({
			"index": index,
			"name": ingredient,
			"quality": "normal",
			"comparator": "=",
			"count": max(1, (48 // len(ingredients)) * get_stack_size(ingredient)),
		})
	return {"sections": [{"index": 1, "filters": filters}]}


def filter_rail_transfer_inserters(blueprint):
	"""Filter inserters that sit directly between a rail and logistics chest.

	Provider-chest transfers use the ingredient named by the nearest train stop.
	Requester-chest transfers use that stop's recipe/product. Fuel policy remains
	separate, so this deliberately does not infer or add coal filters.
	"""
	root = blueprint.get("blueprint", {})
	entities = root.get("entities", [])
	stops = [
		entity for entity in entities
		if entity.get("name") == "train-stop"
		and entity.get("station")
		and not entity["station"].endswith(" midpoint")
	]
	if not stops:
		return blueprint

	provider_names = {"active-provider-chest", "passive-provider-chest"}
	chest_names = provider_names | {"requester-chest"}
	chests_by_position = {
		(entity["position"]["x"], entity["position"]["y"]): entity
		for entity in entities if entity.get("name") in chest_names
	}
	rails = [
		entity for entity in entities
		if entity.get("name") in {"straight-rail", "legacy-straight-rail"}
	]
	# Blueprint directions after the Factorio 2 conversion, expressed in map
	# coordinates from an inserter toward its drop target.
	direction_vectors = {
		0: (0, 1),
		4: (-1, 0),
		8: (0, -1),
		12: (1, 0),
	}

	def nearest_stop(x, y):
		return min(stops, key=lambda stop: (
			(stop["position"]["x"] - x) ** 2
			+ (stop["position"]["y"] - y) ** 2,
			stop["entity_number"],
		))

	def recipe_and_ingredient(station):
		if " dropoff " in station:
			recipe, ingredient = station.split(" dropoff ", 1)
			return recipe, ingredient
		if station.endswith(" pickup"):
			product = station.removesuffix(" pickup")
			return product, product
		return station, station

	for inserter in entities:
		if "inserter" not in inserter.get("name", ""):
			continue
		vector = direction_vectors.get(inserter.get("direction", 0))
		if vector is None:
			continue
		x = inserter["position"]["x"]
		y = inserter["position"]["y"]
		dx, dy = vector
		matched_chest = None
		for chest_side in (1, -1):
			chest = chests_by_position.get((x + chest_side * dx, y + chest_side * dy))
			if chest is None:
				continue
			rail_x = x - chest_side * dx * 1.5
			rail_y = y - chest_side * dy * 1.5
			if any(
				(rail["position"]["x"] - rail_x) ** 2
				+ (rail["position"]["y"] - rail_y) ** 2 <= 0.6
				for rail in rails
			):
				matched_chest = chest
				break
		if matched_chest is None:
			continue

		station = nearest_stop(x, y)["station"]
		recipe, ingredient = recipe_and_ingredient(station)
		item = ingredient if matched_chest["name"] in provider_names else recipe
		inserter["filters"] = [{
			"index": 1,
			"name": item,
			"quality": "normal",
			"comparator": "=",
		}]
	return blueprint


def _load_roboport_station_with_center_pole(place_roboports=True):
	"""Load the roboport station and place a big pole between its substations."""
	blueprint = copy.deepcopy(_load_blueprint_file(ROBOPORT_STATION_TEMPLATE))
	root = blueprint["blueprint"]
	roboports = [
		entity for entity in root["entities"] if entity["name"] == "roboport"
	]
	kept_roboports = roboports[:16] if place_roboports else []
	if place_roboports:
		x_values = [entity["position"]["x"] for entity in root["entities"]]
		y_values = [entity["position"]["y"] for entity in root["entities"]]
		center_x = (min(x_values) + max(x_values)) / 2
		bottom_y = max(y_values) - 6
		for index, entity in enumerate(kept_roboports):
			row, column = divmod(index, 4)
			entity["position"] = {
				"x": center_x + (column - 1.5) * 4,
				"y": bottom_y + (row - 3) * 4,
			}
	removed_numbers = {
		entity["entity_number"] for entity in roboports
		if entity not in kept_roboports
	}
	if removed_numbers:
		root["entities"] = [
			entity for entity in root["entities"]
			if entity["entity_number"] not in removed_numbers
		]
		root["wires"] = [
			wire for wire in root.get("wires", [])
			if wire[0] not in removed_numbers and wire[2] not in removed_numbers
		]
		for entity in root["entities"]:
			if "neighbours" in entity:
				entity["neighbours"] = [
					neighbour for neighbour in entity["neighbours"]
					if neighbour not in removed_numbers
				]
	entities = root["entities"]
	substations = [entity for entity in entities if entity["name"] == "substation"]
	if len(substations) < 2:
		raise ValueError("Roboport station template needs at least two substations")
	first, second = substations[:2]
	entities.append({
		"entity_number": max(entity["entity_number"] for entity in entities) + 1,
		"name": "big-electric-pole",
		"position": {
			"x": (first["position"]["x"] + second["position"]["x"]) / 2,
			"y": (first["position"]["y"] + second["position"]["y"]) / 2,
		},
	})
	return blueprint


def _connect_adjacent_electric_poles(root):
	"""Explicitly wire mutually reachable poles, closest pairs first."""
	wire_reach = {
		"small-electric-pole": 7.5,
		"medium-electric-pole": 9,
		"big-electric-pole": 30,
		"substation": 18,
	}
	poles = [
		entity for entity in root.get("entities", [])
		if entity["name"] in wire_reach
	]
	pole_numbers = {pole["entity_number"] for pole in poles}
	neighbours = {
		pole["entity_number"]: {
			neighbour for neighbour in pole.get("neighbours", [])
			if neighbour in pole_numbers
		}
		for pole in poles
	}
	for pole_number, connected_numbers in list(neighbours.items()):
		for connected_number in connected_numbers:
			neighbours[connected_number].add(pole_number)

	candidates = []
	for index, first in enumerate(poles):
		for second in poles[index + 1:]:
			dx = first["position"]["x"] - second["position"]["x"]
			dy = first["position"]["y"] - second["position"]["y"]
			distance_squared = dx * dx + dy * dy
			maximum_distance = min(
				wire_reach[first["name"]],
				wire_reach[second["name"]],
			)
			if distance_squared <= maximum_distance * maximum_distance:
				candidates.append((distance_squared, first, second))

	for _, first, second in sorted(candidates, key=lambda candidate: candidate[0]):
		first_number = first["entity_number"]
		second_number = second["entity_number"]
		if second_number in neighbours[first_number]:
			continue
		if len(neighbours[first_number]) >= 5 or len(neighbours[second_number]) >= 5:
			continue
		neighbours[first_number].add(second_number)
		neighbours[second_number].add(first_number)

	for pole in poles:
		pole_neighbours = sorted(neighbours[pole["entity_number"]])
		if pole_neighbours:
			pole["neighbours"] = pole_neighbours
		else:
			pole.pop("neighbours", None)


def _make_plastic_bar_station_with_trains(
	inserter="bulk-inserter",
	empty_requester_chests=True,
	trains_per_stop=1,
):
	"""Load the plastic-bar station and add trains from the matching rail map."""
	blueprint = copy.deepcopy(_load_blueprint_file(PLASTIC_BAR_STATION_TEMPLATE))
	root = blueprint["blueprint"]
	train_source_root = _load_blueprint_file(SOLID_INGREDIENT_STATION_TEMPLATE)["blueprint"]
	entities = root["entities"]
	source_entities = train_source_root["entities"]
	_normalize_factorio_2_entity_names(entities, inserter)
	if empty_requester_chests:
		for entity in entities:
			if entity["name"] == "requester-chest":
				entity.pop("request_filters", None)
	else:
		for entity in entities:
			if (
				entity["name"] == "requester-chest"
				and set(_request_filter_names(entity)) == {"utility-science-pack"}
			):
				entity["request_filters"] = _factorio_2_request_filters(
					["plastic-bar"]
				)

	station_positions = {
		entity["station"]: entity["position"]
		for entity in entities
		if entity["name"] == "train-stop"
	}
	source_station_positions = {
		entity["station"]: entity["position"]
		for entity in source_entities
		if entity["name"] == "train-stop"
	}
	common_stations = station_positions.keys() & source_station_positions.keys()
	if not common_stations:
		raise ValueError("Plastic-bar and train templates have no matching train stops")
	anchor_name = next(iter(common_stations))
	offset_x = (
		station_positions[anchor_name]["x"]
		- source_station_positions[anchor_name]["x"]
	)
	offset_y = (
		station_positions[anchor_name]["y"]
		- source_station_positions[anchor_name]["y"]
	)
	for station_name in common_stations:
		if (
			station_positions[station_name]["x"]
			- source_station_positions[station_name]["x"] != offset_x
			or station_positions[station_name]["y"]
			- source_station_positions[station_name]["y"] != offset_y
		):
			raise ValueError("Plastic-bar train-stop geometry does not match the train template")

	rolling_stock_names = {
		"locomotive",
		"cargo-wagon",
		"fluid-wagon",
		"artillery-wagon",
	}
	source_rolling_stock = [
		entity for entity in source_entities if entity["name"] in rolling_stock_names
	]
	next_entity_number = max(entity["entity_number"] for entity in entities) + 1
	entity_numbers = {
		entity["entity_number"]: next_entity_number + index
		for index, entity in enumerate(source_rolling_stock)
	}
	for entity in source_rolling_stock:
		entity_copy = copy.deepcopy(entity)
		entity_copy["entity_number"] = entity_numbers[entity["entity_number"]]
		entity_copy["position"]["x"] += offset_x
		entity_copy["position"]["y"] += offset_y
		entities.append(entity_copy)

	root["stock_connections"] = []
	for connection in train_source_root.get("stock_connections", []):
		connection_copy = copy.deepcopy(connection)
		for key in ("stock", "front", "back"):
			if key in connection_copy:
				connection_copy[key] = entity_numbers[connection_copy[key]]
		root["stock_connections"].append(connection_copy)

	root["schedules"] = []
	for schedule in train_source_root.get("schedules", []):
		schedule_copy = copy.deepcopy(schedule)
		schedule_copy["locomotives"] = [
			entity_numbers[locomotive]
			for locomotive in schedule_copy.get("locomotives", [])
		]
		root["schedules"].append(schedule_copy)

	ingredient_routes = {
		"electronic-circuit": "coal",
		"plastic-bar": "petroleum-gas",
		"copper-cable": "coal",
	}

	def plastic_station_name(station_name):
		for template_ingredient, ingredient in ingredient_routes.items():
			prefix = f"advanced-circuit dropoff {template_ingredient}"
			if station_name.startswith(prefix):
				return station_name.replace(
					prefix,
					f"plastic-bar dropoff {ingredient}",
					1,
				)
			if station_name == f"{template_ingredient} pickup":
				return f"{ingredient} pickup"
		if station_name.startswith("advanced-circuit pickup"):
			return station_name.replace("advanced-circuit", "plastic-bar", 1)
		if station_name == "advanced-circuit dropoff":
			return "plastic-bar dropoff"
		return station_name

	for entity in entities:
		if entity["name"] == "train-stop" and "station" in entity:
			entity["station"] = plastic_station_name(entity["station"])
	_pair_midpoints_with_physical_stops(entities)
	for schedule in root["schedules"]:
		schedule_value = schedule.get("schedule", {})
		records = (
			schedule_value.get("records", [])
			if isinstance(schedule_value, dict)
			else schedule_value
		)
		for record in records:
			if "station" in record:
				record["station"] = plastic_station_name(record["station"])
		ordered_records = _put_midpoint_before_each_scheduled_stop(records)
		if isinstance(schedule_value, dict):
			schedule_value["records"] = ordered_records
		else:
			schedule["schedule"] = ordered_records

	root["label"] = "plastic-bar station"
	return fill_locomotives_with_coal(
		set_trains_per_stop(blueprint, trains_per_stop)
	)


def make_solid_ingredient_station(
	recipe,
	template_path=SOLID_INGREDIENT_STATION_TEMPLATE,
	speed_module="speed-module",
	inserter="bulk-inserter",
	rails_and_roboports=False,
	empty_requester_chests=True,
	trains_per_stop=1,
):
	"""Re-skin the utility-science station map for an all-solid recipe.

	The template's ingredient drop-off stops are assigned ingredients in their
	existing order (repeating when the map contains more stops than ingredients).
	All assemblers and their ingredient requester chests are updated as well.
	"""
	canonical_recipe = resolve_recipe_name(recipe)
	if canonical_recipe is None:
		raise ValueError(f"Unknown recipe: {recipe}")
	if not isinstance(inserter, str) or not inserter.endswith("inserter"):
		raise ValueError("inserter must be a Factorio inserter entity name")
	if not isinstance(rails_and_roboports, bool):
		raise ValueError("rails_and_roboports must be true or false")
	if not isinstance(empty_requester_chests, bool):
		raise ValueError("empty_requester_chests must be true or false")
	if not isinstance(trains_per_stop, int) or isinstance(trains_per_stop, bool):
		raise ValueError("trains_per_stop must be a positive integer")
	if trains_per_stop < 1:
		raise ValueError("trains_per_stop must be a positive integer")

	ingredients = get_recipe(canonical_recipe)
	if not ingredients:
		raise ValueError(f"Recipe has no ingredients: {canonical_recipe}")
	fluid_ingredients = [ingredient for ingredient in ingredients if is_fluid(ingredient)]
	if fluid_ingredients:
		raise ValueError(
			f"{canonical_recipe} is not an all-solid recipe; fluid ingredients: "
			+ ", ".join(fluid_ingredients)
		)

	blueprint = _load_blueprint_file(template_path)
	blueprint = copy.deepcopy(blueprint)
	entities = blueprint["blueprint"]["entities"]
	_normalize_factorio_2_entity_names(entities, inserter)

	assembler_entities = [
		entity for entity in entities if entity["name"].startswith("assembling-machine-")
	]
	if not assembler_entities:
		raise ValueError("Solid-ingredient station template contains no assemblers")
	production_machine = get_recipe_machine(canonical_recipe)
	if production_machine not in ("assembling-machine-3", "electric-furnace"):
		raise ValueError(
			f"{canonical_recipe} cannot be made in an assembler or electric furnace"
		)
	template_recipe = assembler_entities[0].get("recipe", "utility-science-pack")
	template_ingredients = set(get_recipe(template_recipe) or [])
	request_filters = _factorio_2_request_filters(ingredients)
	root = blueprint["blueprint"]
	original_schedules = copy.deepcopy(root.get("schedules", []))

	dropoff_number = 0
	for entity in entities:
		if entity["name"].startswith("assembling-machine-"):
			entity["name"] = production_machine
			entity["recipe"] = canonical_recipe
			entity["recipe_quality"] = "normal"
		elif entity["name"] == "train-stop" and "station" in entity:
			station = entity["station"]
			if station.endswith(" midpoint"):
				continue
			if " pickup" in station:
				entity["station"] = f"{canonical_recipe} pickup"
			elif " dropoff " in station:
				ingredient = ingredients[dropoff_number % len(ingredients)]
				entity["station"] = f"{canonical_recipe} dropoff {ingredient}"
				dropoff_number += 1
		elif entity["name"] in ("requester-chest", "logistic-chest-requester"):
			if empty_requester_chests:
				entity.pop("request_filters", None)
			else:
				existing_names = set(_request_filter_names(entity))
				if existing_names in ({template_recipe}, {"utility-science-pack"}):
					# These chests move the completed item to the pickup station.
					# Leaving the template product here made every generated station
					# request utility science packs.
					entity["request_filters"] = _factorio_2_request_filters(
						[canonical_recipe]
					)
				elif existing_names and existing_names.issubset(template_ingredients):
					entity["request_filters"] = copy.deepcopy(request_filters)

	if dropoff_number == 0:
		# Older exported station blueprints can contain player-generated stop
		# names rather than semantic pickup/dropoff names. Use the stop nearest
		# the captured locomotive as the product pickup and assign every other
		# stop to an ingredient in stable entity order.
		train_stops = [entity for entity in entities if entity["name"] == "train-stop"]
		locomotives = [entity for entity in entities if entity["name"] == "locomotive"]
		if len(train_stops) < 2:
			raise ValueError("Solid-ingredient station template needs at least two stops")
		if locomotives:
			pickup_stop = min(
				train_stops,
				key=lambda stop: min(
					(stop["position"]["x"] - locomotive["position"]["x"]) ** 2
					+ (stop["position"]["y"] - locomotive["position"]["y"]) ** 2
					for locomotive in locomotives
				),
			)
		else:
			pickup_stop = train_stops[0]
		pickup_stop["station"] = f"{canonical_recipe} pickup"
		for stop in train_stops:
			if stop is pickup_stop:
				continue
			ingredient = ingredients[dropoff_number % len(ingredients)]
			stop["station"] = f"{canonical_recipe} dropoff {ingredient}"
			dropoff_number += 1

	_pair_midpoints_with_physical_stops(entities)

	filter_rail_transfer_inserters(blueprint)

	# Build fresh schedules from the current template geometry. Sort both stops
	# and trains by coordinates, then greedily assign the nearest unassigned
	# consist to each stop. A route begins at its local endpoint, passes through
	# each endpoint's named midpoint immediately before visiting that endpoint.
	entities_by_number = {entity["entity_number"]: entity for entity in entities}
	stock_graph = {}
	for connection in root.get("stock_connections", []):
		stock = connection["stock"]
		stock_graph.setdefault(stock, set())
		for end in ("front", "back"):
			if end in connection:
				other_stock = connection[end]
				stock_graph[stock].add(other_stock)
				stock_graph.setdefault(other_stock, set()).add(stock)

	consists = []
	seen_stock = set()
	for stock in stock_graph:
		if stock in seen_stock:
			continue
		component = []
		pending = [stock]
		seen_stock.add(stock)
		while pending:
			current = pending.pop()
			component.append(current)
			for neighbour in stock_graph[current]:
				if neighbour not in seen_stock:
					seen_stock.add(neighbour)
					pending.append(neighbour)
		consists.append(component)

	consists = [
		{
			"stock": consist,
			"locomotives": sorted([
				stock for stock in consist
				if entities_by_number[stock]["name"] == "locomotive"
			], key=lambda locomotive: (
				entities_by_number[locomotive]["position"]["y"],
				entities_by_number[locomotive]["position"]["x"],
				locomotive,
			)),
		}
		for consist in consists
	]
	consists = [consist for consist in consists if consist["locomotives"]]
	coordinate_key = lambda entity: (
		entity["position"]["y"],
		entity["position"]["x"],
		entity["entity_number"],
	)
	non_midpoint_stops = sorted([
		entity for entity in entities
		if entity["name"] == "train-stop"
		and not entity["station"].endswith(" midpoint")
	], key=coordinate_key)
	midpoints = sorted([
		entity for entity in entities
		if entity["name"] == "train-stop"
		and entity.get("station", "").endswith(" midpoint")
	], key=coordinate_key)
	midpoints_by_name = {
		midpoint["station"]: midpoint for midpoint in midpoints
	}

	if consists and len(consists) < len(non_midpoint_stops):
		raise ValueError("Station template does not contain a train for every stop")
	if consists and not midpoints:
		raise ValueError("Station template contains no midpoint stops")

	def distance_to_locomotives(stop, consist):
		return min(
			(stop["position"]["x"] - entities_by_number[locomotive]["position"]["x"]) ** 2
			+ (stop["position"]["y"] - entities_by_number[locomotive]["position"]["y"]) ** 2
			for locomotive in consist["locomotives"]
		)

	root["schedules"] = []
	unassigned_consists = sorted(consists, key=lambda consist: coordinate_key(
		entities_by_number[consist["locomotives"][0]]
	))
	for local_stop in non_midpoint_stops:
		if not unassigned_consists:
			break
		consist = min(
			unassigned_consists,
			key=lambda candidate: (
				distance_to_locomotives(local_stop, candidate),
				coordinate_key(entities_by_number[candidate["locomotives"][0]]),
			),
		)
		unassigned_consists.remove(consist)
		midpoint_name = f'{local_stop["station"]} midpoint'
		midpoint = midpoints_by_name.get(midpoint_name)
		if midpoint is None:
			raise ValueError(
				f"Station template contains no matching midpoint: {midpoint_name}"
			)

		if local_stop["station"] == f"{canonical_recipe} pickup":
			local_wait_type = "full"
			remote_station = f"{canonical_recipe} dropoff"
			remote_wait_type = "empty"
		else:
			ingredient = local_stop["station"].removeprefix(
				f"{canonical_recipe} dropoff "
			)
			local_wait_type = "empty"
			remote_station = f"{ingredient} pickup"
			remote_wait_type = "full"

		records = [
			{
				"station": local_stop["station"],
				"wait_conditions": [{
					"type": local_wait_type,
					"compare_type": "and",
				}],
			},
			{
				"station": remote_station,
				"wait_conditions": [{
					"type": remote_wait_type,
					"compare_type": "and",
				}],
			},
		]
		root["schedules"].append({
			"locomotives": consist["locomotives"],
			"schedule": {"records": _put_midpoint_before_each_scheduled_stop(records)},
		})

	# Factorio 1.x blueprints contain locomotives and schedules but no
	# stock_connections collection. Preserve those captured trains and rewrite
	# their legacy schedule to the generated product route.
	if not consists and original_schedules:
		root["schedules"] = original_schedules
		for schedule in root["schedules"]:
			records = schedule.get("schedule", [])
			if isinstance(records, dict):
				records["records"] = [
					{
						"station": f"{canonical_recipe} pickup",
						"wait_conditions": [{"type": "full", "compare_type": "and"}],
					},
					{
						"station": f"{canonical_recipe} dropoff",
						"wait_conditions": [{"type": "empty", "compare_type": "and"}],
					},
				]
			else:
				schedule["schedule"] = [
					{
						"station": f"{canonical_recipe} pickup",
						"wait_conditions": [{"type": "full", "compare_type": "and"}],
					},
					{
						"station": f"{canonical_recipe} dropoff",
						"wait_conditions": [{"type": "empty", "compare_type": "and"}],
					},
				]
			schedule["schedule"] = add_midpoints_to_train_schedule(
				schedule["schedule"]
			)
	if rails_and_roboports:
		rail_entity_names = {
			"straight-rail",
			"curved-rail",
			"curved-rail-a",
			"curved-rail-b",
			"half-diagonal-rail",
			"rail-ramp",
			"rail-support",
			"rail-signal",
			"rail-chain-signal",
		}
		rail_entities = [
			copy.deepcopy(entity) for entity in entities
			if entity["name"] in rail_entity_names
		]
		if not rail_entities:
			raise ValueError("Station template contains no rails or rail signals")

		min_x = min(entity["position"]["x"] for entity in rail_entities)
		max_x = max(entity["position"]["x"] for entity in rail_entities)
		max_y = max(entity["position"]["y"] for entity in rail_entities)
		roboport_x_positions = []
		x = math.ceil((min_x + 2) / 4) * 4
		while x <= max_x - 2:
			roboport_x_positions.append(x)
			x += 4
		if not roboport_x_positions:
			roboport_x_positions = [(min_x + max_x) / 2]

		next_entity_number = max(
			entity["entity_number"] for entity in rail_entities
		) + 1
		for row in range(3):
			for roboport_x in roboport_x_positions:
				rail_entities.append({
					"entity_number": next_entity_number,
					"name": "roboport",
					"position": {
						"x": roboport_x,
						"y": max_y + 2 + row * 4,
					},
				})
				next_entity_number += 1

		root["entities"] = rail_entities
		root.pop("wires", None)
		root.pop("schedules", None)
		root.pop("stock_connections", None)
		root["label"] = f"{canonical_recipe} rails and roboports"
		return blueprint

	return fill_locomotives_with_coal(set_trains_per_stop(
		add_max_modules(blueprint, speed_module),
		trains_per_stop,
	))


def make_solid_ingredient_station_array(
	recipes,
	count=None,
	rows=None,
	cols=None,
	horizontal_spacing=10,
	vertical_spacing=10,
	include_roboports=False,
	place_roboports_in_squares=True,
	place_roboports_between_stations=True,
	include_intersections=True,
	intersection_x_offset=0,
	intersection_y_offset=-6,
	intersection_signal_y_offset=1,
	empty_requester_chests=True,
	inserter="bulk-inserter",
	**station_options,
):
	"""Create a grid from a recipe name or list of recipe names.

	A list is laid out in order. If an explicit ``rows`` by ``cols`` grid is too
	small, recipes beyond its capacity are discarded. If ``include_roboports``
	is true, every production row gets a full roboport-station row above it.
	An intersection blueprint is centered at every corner shared by four cells.
	``intersection_x_offset`` and ``intersection_y_offset`` adjust its position.
	Negative X/Y values move it left/up; positive values move it right/down.
	``intersection_signal_y_offset`` moves only its rail signals vertically.
	"""
	for name, value in (
		("count", count),
		("rows", rows),
		("cols", cols),
	):
		if value is not None and (not isinstance(value, int) or value < 1):
			raise ValueError(f"{name} must be a positive integer")
	for name, value in (
		("horizontal_spacing", horizontal_spacing),
		("vertical_spacing", vertical_spacing),
	):
		if not isinstance(value, (int, float)) or value < 0:
			raise ValueError(f"{name} must be a non-negative number")
	if not isinstance(include_roboports, bool):
		raise ValueError("include_roboports must be true or false")
	if not isinstance(place_roboports_in_squares, bool):
		raise ValueError("place_roboports_in_squares must be true or false")
	if not isinstance(place_roboports_between_stations, bool):
		raise ValueError("place_roboports_between_stations must be true or false")
	if not isinstance(include_intersections, bool):
		raise ValueError("include_intersections must be true or false")
	if not isinstance(empty_requester_chests, bool):
		raise ValueError("empty_requester_chests must be true or false")
	trains_per_stop = station_options.get("trains_per_stop", 1)
	if not isinstance(trains_per_stop, int) or isinstance(trains_per_stop, bool):
		raise ValueError("trains_per_stop must be a positive integer")
	if trains_per_stop < 1:
		raise ValueError("trains_per_stop must be a positive integer")
	for name, value in (
		("intersection_x_offset", intersection_x_offset),
		("intersection_y_offset", intersection_y_offset),
		("intersection_signal_y_offset", intersection_signal_y_offset),
	):
		if not isinstance(value, (int, float)):
			raise ValueError(f"{name} must be a number")

	if isinstance(recipes, str):
		if count is None:
			count = rows * cols if rows is not None and cols is not None else 1
		recipe_list = [recipes] * count
		station_model_list = [None] * count
	else:
		recipe_entries = list(recipes)
		if not recipe_entries:
			raise ValueError("recipes must contain at least one recipe")
		if not all(
			(isinstance(entry, str) and entry)
			or (isinstance(getattr(entry, "product", None), str) and entry.product)
			for entry in recipe_entries
		):
			raise ValueError("every recipe must be a name or Station object")
		recipe_list = [
			entry if isinstance(entry, str) else entry.product
			for entry in recipe_entries
		]
		station_model_list = [
			None if isinstance(entry, str) else entry for entry in recipe_entries
		]
		if count is not None:
			recipe_list = recipe_list[:count]
			station_model_list = station_model_list[:count]
		count = len(recipe_list)

	if rows is None and cols is None:
		cols = math.ceil(math.sqrt(count))
		rows = math.ceil(count / cols)
	elif rows is None:
		rows = math.ceil(count / cols)
	elif cols is None:
		cols = math.ceil(count / rows)

	capacity = rows * cols
	recipe_list = recipe_list[:capacity]
	station_model_list = station_model_list[:capacity]
	count = len(recipe_list)
	if count == 0:
		raise ValueError("The requested grid has no room for a station")

	station_recipe_list = []
	station_models = []
	for row in range(rows):
		row_recipes = recipe_list[row * cols:(row + 1) * cols]
		row_models = station_model_list[row * cols:(row + 1) * cols]
		if not row_recipes:
			break
		if include_roboports:
			station_recipe_list.extend(["roboport_station"] * cols)
			station_models.extend([None] * cols)
		station_recipe_list.extend(row_recipes)
		station_models.extend(row_models)

	def build_station_blueprint(recipe, model):
		model_trains = (
			model.trains_per_station if model is not None else trains_per_stop
		)
		model_inserter = (
			model.inserter_type
			if model is not None else inserter
		)
		if model is not None and empty_requester_chests:
			return model.get_blueprint()
		if recipe in ROBOPORT_STATION_ALIASES:
			return _load_roboport_station_with_center_pole(place_roboports_in_squares)
		if recipe == "plastic-bar":
			return _make_plastic_bar_station_with_trains(
				model_inserter,
				empty_requester_chests,
				model_trains,
			)
		options = dict(station_options)
		options["trains_per_stop"] = model_trains
		options["inserter"] = model_inserter
		return make_solid_ingredient_station(
			recipe,
			empty_requester_chests=empty_requester_chests,
			**options,
		)

	stations = [
		build_station_blueprint(recipe, model)
		for recipe, model in zip(station_recipe_list, station_models)
	]
	station_roots = [station["blueprint"] for station in stations]
	if any(not root.get("entities") for root in station_roots):
		raise ValueError("Generated station contains no entities")

	widths = []
	heights = []
	station_bounds = []
	for root in station_roots:
		station_entities = root["entities"]
		x_values = [entity["position"]["x"] for entity in station_entities]
		y_values = [entity["position"]["y"] for entity in station_entities]
		bounds = (min(x_values), max(x_values), min(y_values), max(y_values))
		station_bounds.append(bounds)
		widths.append(bounds[1] - bounds[0])
		heights.append(bounds[3] - bounds[2])
	# Rail positions are tied to Factorio's two-tile grid. Keep every station
	# translation even so copying it into the array cannot change rail parity.
	step_x = math.ceil((max(widths) + horizontal_spacing) / 2) * 2
	step_y = math.ceil((max(heights) + vertical_spacing) / 2) * 2

	result = copy.deepcopy(stations[0])
	result_root = result["blueprint"]
	for collection in ("entities", "wires", "schedules", "stock_connections"):
		result_root[collection] = []

	def remap_entity_references(value, entity_numbers):
		if isinstance(value, dict):
			for key, nested_value in value.items():
				if key == "entity_id" and nested_value in entity_numbers:
					value[key] = entity_numbers[nested_value]
				else:
					remap_entity_references(nested_value, entity_numbers)
		elif isinstance(value, list):
			for nested_value in value:
				remap_entity_references(nested_value, entity_numbers)

	next_entity_number = 1
	cell_straight_rails = {}
	next_physical_station_id = 1
	for station_index, station_root in enumerate(station_roots):
		row, col = divmod(station_index, cols)
		station_recipe = station_recipe_list[station_index]
		station_model = station_models[station_index]
		station_token = None
		if station_recipe not in ROBOPORT_STATION_ALIASES:
			station_recipe = station_recipe.replace(" ", "-")
			station_token = (
				station_model.id if station_model is not None
				else f"{station_recipe}-{next_physical_station_id:03d}"
			)
			next_physical_station_id += 1

		def identify_local_stop(station_name):
			if station_token is None or not station_name:
				return station_name
			if station_name == f"{station_recipe} pickup":
				return f"{station_token} pickup"
			if station_name == f"{station_recipe} pickup midpoint":
				return f"{station_token} pickup midpoint"
			prefix = f"{station_recipe} dropoff "
			if station_name.startswith(prefix):
				return f"{station_token} dropoff {station_name[len(prefix):]}"
			return station_name

		cell_straight_rails[(row, col)] = []
		station_entities = station_root["entities"]
		station_min_x, _, station_min_y, _ = station_bounds[station_index]
		rail_entities = [
			entity for entity in station_entities if "rail" in entity["name"]
		]
		if rail_entities:
			# These station templates are derived from the same rail scaffold.
			# Align their first saved rail at (1, 1); their non-rail bounds differ
			# slightly and are not a reliable common origin.
			rail_anchor = min(
				rail_entities,
				key=lambda entity: entity["entity_number"],
			)
			station_origin_x = rail_anchor["position"]["x"] - 1
			station_origin_y = rail_anchor["position"]["y"] - 1
		else:
			station_origin_x = math.floor(station_min_x / 2) * 2
			station_origin_y = math.floor(station_min_y / 2) * 2
		entity_numbers = {
			entity["entity_number"]: next_entity_number + index
			for index, entity in enumerate(station_entities)
		}

		for entity in station_entities:
			entity_copy = copy.deepcopy(entity)
			old_number = entity_copy["entity_number"]
			entity_copy["entity_number"] = entity_numbers[old_number]
			entity_copy["position"]["x"] += col * step_x - station_origin_x
			entity_copy["position"]["y"] += row * step_y - station_origin_y
			if "neighbours" in entity_copy:
				entity_copy["neighbours"] = [
					entity_numbers[neighbour]
					for neighbour in entity_copy["neighbours"]
					if neighbour in entity_numbers
				]
			remap_entity_references(entity_copy.get("connections"), entity_numbers)
			if entity_copy.get("name") == "train-stop":
				entity_copy["station"] = identify_local_stop(
					entity_copy.get("station")
				)
			result_root["entities"].append(entity_copy)
			if entity_copy["name"] == "straight-rail":
				cell_straight_rails[(row, col)].append(entity_copy)

		for wire in station_root.get("wires", []):
			wire_copy = copy.deepcopy(wire)
			wire_copy[0] = entity_numbers[wire_copy[0]]
			wire_copy[2] = entity_numbers[wire_copy[2]]
			result_root["wires"].append(wire_copy)

		for schedule in station_root.get("schedules", []):
			schedule_copy = copy.deepcopy(schedule)
			schedule_copy["_station_index"] = station_index
			schedule_copy["_station_token"] = station_token
			schedule_copy["_station_recipe"] = station_recipe
			schedule_value = schedule_copy.get("schedule", {})
			records = (
				schedule_value.get("records", [])
				if isinstance(schedule_value, dict) else schedule_value
			)
			for record in records:
				record["station"] = identify_local_stop(record.get("station"))
			schedule_copy["locomotives"] = [
				entity_numbers[locomotive]
				for locomotive in schedule_copy.get("locomotives", [])
			]
			result_root["schedules"].append(schedule_copy)

		for connection in station_root.get("stock_connections", []):
			connection_copy = copy.deepcopy(connection)
			for key in ("stock", "front", "back"):
				if key in connection_copy:
					connection_copy[key] = entity_numbers[connection_copy[key]]
			result_root["stock_connections"].append(connection_copy)

		next_entity_number += len(station_entities)

	if not include_intersections:
		# Continue every matching perimeter rail straight across the spacing
		# between adjacent cells. This keeps the no-intersection layout routable
		# without adding turns or crossings.
		existing_straight_rails = {
			(
				entity["position"]["x"],
				entity["position"]["y"],
				entity.get("direction", 0),
			)
			for entity in result_root["entities"]
			if entity["name"] == "straight-rail"
		}

		def add_straight_rail(x, y, direction):
			nonlocal next_entity_number
			key = (x, y, direction)
			if key in existing_straight_rails:
				return
			result_root["entities"].append({
				"entity_number": next_entity_number,
				"name": "straight-rail",
				"position": {"x": x, "y": y},
				**({"direction": direction} if direction else {}),
			})
			next_entity_number += 1
			existing_straight_rails.add(key)

		for (row, col), rails in cell_straight_rails.items():
			right_rails = cell_straight_rails.get((row, col + 1))
			if right_rails:
				left_edges = {}
				right_edges = {}
				for rail in rails:
					if rail.get("direction", 0) == 4:
						y = rail["position"]["y"]
						left_edges[y] = max(
							left_edges.get(y, -math.inf), rail["position"]["x"]
						)
				for rail in right_rails:
					if rail.get("direction", 0) == 4:
						y = rail["position"]["y"]
						right_edges[y] = min(
							right_edges.get(y, math.inf), rail["position"]["x"]
						)
				for y in left_edges.keys() & right_edges.keys():
					left_x, right_x = left_edges[y], right_edges[y]
					if 2 < right_x - left_x <= horizontal_spacing + 8:
						for x in range(int(left_x + 2), int(right_x), 2):
							add_straight_rail(x, y, 4)

			bottom_rails = cell_straight_rails.get((row + 1, col))
			if bottom_rails:
				top_edges = {}
				bottom_edges = {}
				for rail in rails:
					if rail.get("direction", 0) == 0:
						x = rail["position"]["x"]
						top_edges[x] = max(
							top_edges.get(x, -math.inf), rail["position"]["y"]
						)
				for rail in bottom_rails:
					if rail.get("direction", 0) == 0:
						x = rail["position"]["x"]
						bottom_edges[x] = min(
							bottom_edges.get(x, math.inf), rail["position"]["y"]
						)
				for x in top_edges.keys() & bottom_edges.keys():
					top_y, bottom_y = top_edges[x], bottom_edges[x]
					if 2 < bottom_y - top_y <= vertical_spacing + 8:
						for y in range(int(top_y + 2), int(bottom_y), 2):
							add_straight_rail(x, y, 0)

	if include_intersections:
		intersection_root = _load_blueprint_file(INTERSECTION_TEMPLATE)["blueprint"]
		intersection_entities = intersection_root.get("entities", [])
		if not intersection_entities:
			raise ValueError("Intersection template contains no entities")

		intersection_x_values = [
			entity["position"]["x"] for entity in intersection_entities
		]
		intersection_y_values = [
			entity["position"]["y"] for entity in intersection_entities
		]
		intersection_center_x = (
			min(intersection_x_values) + max(intersection_x_values)
		) / 2
		intersection_center_y = (
			min(intersection_y_values) + max(intersection_y_values)
		) / 2
		occupied_cells = {
			divmod(index, cols) for index in range(len(station_roots))
		}
		existing_rails = {
			(
				entity["name"],
				entity["position"]["x"],
				entity["position"]["y"],
				entity.get("direction", 0),
			)
			for entity in result_root["entities"]
			if "rail" in entity["name"]
		}

		layout_rows = math.ceil(len(station_roots) / cols)
		for junction_row in range(1, layout_rows):
			for junction_col in range(1, cols):
				surrounding_cells = {
					(junction_row - 1, junction_col - 1),
					(junction_row - 1, junction_col),
					(junction_row, junction_col - 1),
					(junction_row, junction_col),
				}
				if not surrounding_cells.issubset(occupied_cells):
					continue

				# Round the first junction once, then advance by exact cell steps.
				# Rounding each half-tile center independently causes alternating
				# rows to move because Python uses tie-to-even rounding.
				first_offset_x = round(
					(step_x - intersection_center_x) / 2
				) * 2 + intersection_x_offset
				first_offset_y = round(
					(step_y - intersection_center_y) / 2
				) * 2 + intersection_y_offset
				offset_x = first_offset_x + (junction_col - 1) * step_x
				offset_y = first_offset_y + (junction_row - 1) * step_y
				for entity in intersection_entities:
					entity_copy = copy.deepcopy(entity)
					entity_copy["position"]["x"] += offset_x
					entity_copy["position"]["y"] += offset_y
					if entity_copy["name"] in ("rail-signal", "rail-chain-signal"):
						entity_copy["position"]["y"] += intersection_signal_y_offset
					rail_key = (
						entity_copy["name"],
						entity_copy["position"]["x"],
						entity_copy["position"]["y"],
						entity_copy.get("direction", 0),
					)
					if rail_key in existing_rails:
						continue
					entity_copy["entity_number"] = next_entity_number
					next_entity_number += 1
					result_root["entities"].append(entity_copy)
					existing_rails.add(rail_key)


				# Place one roboport near the top eighth of the intersection. Exact
				# horizontal center overlaps a rail, so use the nearest clear spot.
				# The second big pole is 30 tiles below the first, the maximum wire
				# reach, and both poles are explicitly connected.
				intersection_top = min(intersection_y_values)
				intersection_height = (
					max(intersection_y_values) - intersection_top
				)
				roboport_x = intersection_center_x - 2 + offset_x
				roboport_y = round(
					intersection_top + intersection_height / 8
				) + offset_y
				if place_roboports_between_stations:
					result_root["entities"].append({
						"entity_number": next_entity_number,
						"name": "roboport",
						"position": {"x": roboport_x, "y": roboport_y},
					})
					next_entity_number += 1
				upper_pole_number = next_entity_number
				lower_pole_number = next_entity_number + 1
				result_root["entities"].append({
					"entity_number": upper_pole_number,
					"name": "big-electric-pole",
					"position": {"x": roboport_x - 3, "y": roboport_y},
					"neighbours": [lower_pole_number],
				})
				result_root["entities"].append({
					"entity_number": lower_pole_number,
					"name": "big-electric-pole",
					"position": {"x": roboport_x - 3, "y": roboport_y + 30},
					"neighbours": [upper_pole_number],
				})
				next_entity_number += 2

	products = ", ".join(dict.fromkeys(recipe_list))
	roboport_label = ", with roboport rows" if include_roboports else ""
	intersection_label = ", with intersections" if include_intersections else ""
	result_root["label"] = (
		f"{products} station array ({rows}x{cols}, {count} stations"
		f"{roboport_label}{intersection_label})"
	)
	_connect_adjacent_electric_poles(result_root)
	_normalize_factorio_2_entity_names(result_root["entities"], inserter)
	return fill_locomotives_with_coal(
		set_trains_per_stop(result, trains_per_stop)
	)

def make_general_blueprint_array(blueprints,rows=None,cols=None):
	cell_dims =   3,5 #get_station_dimensions(blueprints[-1])
	print(cell_dims)
	total_blueprint = copy.deepcopy(blueprints[0])

	total_blueprint["blueprint"]["entities"] = []
	if rows == None and cols == None:
		rows,cols = [math.ceil(math.sqrt(len(blueprints)))]*2
	entity_number = 1
	print(rows,cols)
	for i in range(rows):
		for j in range(cols):
			
			# print(len(blueprints))
			next_entities = blueprints[0]["blueprint"]["entities"]
			blueprints.pop(0)
			for k,v in enumerate(next_entities):
				v["position"]["x"] += cell_dims[0]*j
				v["position"]["y"] += cell_dims[1]*i
				v["items"] = {"speed-module-2":4}
				v["entity_number"] = entity_number
				entity_number +=1
				total_blueprint["blueprint"]["entities"].append(v)
			if not blueprints:
				return total_blueprint
	return total_blueprint


