def zero_out_x_y_coordinates(blueprint):
	min_x = min([int(v["position"]["x"]) for i,v in enumerate(blueprint["blueprint"]["entities"])])
	min_y = min([int(v["position"]["y"]) for i,v in enumerate(blueprint["blueprint"]["entities"])])
	# min_x,min_y = int(min_x), int(min_y)
	blueprint_copy = copy.deepcopy(blueprint)

	for i,v in enumerate(blueprint_copy["blueprint"]["entities"]):
		
		v["position"]["x"] -= min_x - 1
		blueprint_copy[i] =v
	return blueprint_copy

def make_station(product, trains_per_stop=1, inserter="bulk-inserter"):
	blueprint = get_template_for_assembling_machines_or_smelters()
	production_type = get_production_type(product)
	production_types = ["chemical_plant_fluids_from_two_fluids", "chemical_plant_solids_from_two_fluids", 
						"chemical_plant_fluids_from_one_fluid", "chemical_plant_solids_from_one_fluid", 
						"assembling-machine-with-one-fluid", "assembling-machine or smelter"]
	chemical_production_types = production_types[:4]

	# if production_type == "chemical_plant_fluids_from_one_fluid":
	if production_type in chemical_production_types:
		blueprint =  convert_assembling_recipe(blueprint,product,production_type)
	elif product == "processing-unit" or product == "electric-engine-unit":
		blueprint = convert_assembling_recipe(blueprint, product)

	elif production_type == "assembling-machine or smelter":
		blueprint =  convert_assembling_recipe(blueprint,product)
	blueprint = zero_out_x_y_coordinates(blueprint)
	for i in copy.deepcopy(blueprint):
		if isinstance(i,str):
			if i.isnumeric():
				blueprint.pop(i)

	_normalize_factorio_2_entity_names(
		blueprint.get("blueprint", {}).get("entities", []), inserter
	)
	return fill_locomotives_with_coal(
		set_trains_per_stop(blueprint, trains_per_stop)
	)


def make_station_row(
	products,
	spacing=4,
	trains_per_stop=1,
	inserter="bulk-inserter",
):
	"""Build complete product stations and place them left-to-right in one row."""
	if isinstance(products, str):
		products = [products]
	products = list(products)
	if not products:
		raise ValueError("products must contain at least one product")

	stations = [
		make_station(
			product,
			trains_per_stop=trains_per_stop,
			inserter=inserter,
		)
		for product in products
	]
	result = copy.deepcopy(stations[0])
	result_root = result["blueprint"]
	result_root["entities"] = []
	result_root.pop("wires", None)
	next_entity_number = 1
	next_x = 0

	def remap_connections(value, entity_numbers):
		if isinstance(value, dict):
			for key, nested_value in value.items():
				if key == "entity_id" and nested_value in entity_numbers:
					value[key] = entity_numbers[nested_value]
				else:
					remap_connections(nested_value, entity_numbers)
		elif isinstance(value, list):
			for nested_value in value:
				remap_connections(nested_value, entity_numbers)

	for station in stations:
		station_root = station["blueprint"]
		entities = station_root.get("entities", [])
		if not entities:
			continue

		min_x = min(entity["position"]["x"] for entity in entities)
		max_x = max(entity["position"]["x"] for entity in entities)
		min_y = min(entity["position"]["y"] for entity in entities)
		entity_numbers = {
			entity["entity_number"]: next_entity_number + index
			for index, entity in enumerate(entities)
		}

		for entity in entities:
			entity_copy = copy.deepcopy(entity)
			old_number = entity_copy["entity_number"]
			entity_copy["entity_number"] = entity_numbers[old_number]
			entity_copy["position"]["x"] += next_x - min_x
			entity_copy["position"]["y"] -= min_y
			if "neighbours" in entity_copy:
				entity_copy["neighbours"] = [
					entity_numbers[neighbour]
					for neighbour in entity_copy["neighbours"]
					if neighbour in entity_numbers
				]
			remap_connections(entity_copy.get("connections"), entity_numbers)
			result_root["entities"].append(entity_copy)

		for wire in station_root.get("wires", []):
			wire_copy = copy.deepcopy(wire)
			wire_copy[0] = entity_numbers[wire_copy[0]]
			wire_copy[2] = entity_numbers[wire_copy[2]]
			result_root.setdefault("wires", []).append(wire_copy)

		next_entity_number += len(entities)
		next_x += max_x - min_x + spacing

	return fill_locomotives_with_coal(result)


def get_train_stops(blueprint):
	train_stops = defaultdict(int)
	for i,v in enumerate(blueprint["blueprint"]["entities"]):
		if v["name"] == "train-stop":
			if "sulfur" in v["station"]:
				print(v["station"])
			train_stops[v["station"]] += 1
	return train_stops

def get_station_dimensions(station=None):
	if not station:
		station = get_template_for_assembling_machines_or_smelters()

	min_x, min_y = station["blueprint"]["entities"][0]["position"].values()
	max_x, max_y = station["blueprint"]["entities"][0]["position"].values()

	for i,v in enumerate(station["blueprint"]["entities"][1:]):

		x,y = v["position"].values()
		if x < min_x:
			min_x = x
		if x > max_x:
			max_x =x
		if y < min_y:
			min_y = y
		if y > max_y:
			max_y = y
	return max_x - min_x, max_y- min_y

def find_extreme_intersections(blueprint):
	train_coordinates = {1:[], 2:[]}
	for i,v in enumerate(blueprint["blueprint"]["entities"]):
		if v["name"] == "straight-rail":
			train_coordinates[2*("direction" in v)+1*(not "direction" in v)].append([v["position"]["x"],v["position"]["y"]])
	#get intersections
	intersections = []
	for coordinate in train_coordinates[1]:
		if coordinate in train_coordinates[2]:
			intersections.append(coordinate)
	intersections.sort()
	return intersections[0],intersections[-1]


